"use client";

import {
  type ColumnFiltersState,
  type ColumnVisibilityState,
  type RowSelectionState,
  type SortingState,
  useTable,
} from "@tanstack/react-table";
import React from "react";
import { dataTableFeatures } from "@/components/ui/data-table";
import {
  EMPTY_DRAFT,
  INITIAL_TASKS,
  type Task,
  type TaskDraft,
  type TaskEditorState,
  type TaskStatus,
} from "@/components/tasks/data/tasks";
import { createTaskColumns } from "@/components/tasks/task-columns";
import { TaskEditorDialog } from "@/components/tasks/task-editor-dialog";
import { TaskFilters } from "@/components/tasks/task-filters";
import { TaskGrid } from "@/components/tasks/task-grid";
import { TaskSelectionActionBar } from "@/components/tasks/task-selection-action-bar";

const INITIAL_ROW_SELECTION: RowSelectionState = {
  "PRD-1042": true,
  "PRD-1061": true,
  "PRD-1075": true,
};

export const TaskTable = () => {
  const [tasks, setTasks] = React.useState(INITIAL_TASKS);
  const [columnFilters, setColumnFilters] = React.useState<ColumnFiltersState>(
    []
  );
  const [columnVisibility, setColumnVisibility] =
    React.useState<ColumnVisibilityState>({});
  const [rowSelection, setRowSelection] = React.useState<RowSelectionState>(
    INITIAL_ROW_SELECTION
  );
  const [sorting, setSorting] = React.useState<SortingState>([]);
  const [nextTaskNumber, setNextTaskNumber] = React.useState(1110);
  const [editor, setEditor] = React.useState<TaskEditorState | null>(null);
  const [draft, setDraft] = React.useState<TaskDraft>(EMPTY_DRAFT);

  const closeEditor = () => {
    setDraft(EMPTY_DRAFT);
    setEditor(null);
  };

  const openCreateEditor = () => {
    setDraft(EMPTY_DRAFT);
    setEditor({ mode: "create" });
  };

  const openEditEditor = (task: Task) => {
    setDraft({
      assigneeId: task.assigneeId,
      priority: task.priority,
      status: task.status,
      title: task.title,
      type: task.type,
    });
    setEditor({ mode: "edit", taskId: task.id });
  };

  const allocateTaskId = () => {
    const id = `PRD-${nextTaskNumber}`;
    setNextTaskNumber((current) => current + 1);
    return id;
  };

  const saveTask = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const title = draft.title.trim();
    if (!(title && editor)) {
      return;
    }

    if (editor.mode === "create") {
      const id = allocateTaskId();

      setTasks((currentTasks) => [
        {
          ...draft,
          id,
          title,
        },
        ...currentTasks,
      ]);
    } else if (editor.taskId) {
      setTasks((currentTasks) =>
        currentTasks.map((task) =>
          task.id === editor.taskId ? { ...task, ...draft, title } : task
        )
      );
    }

    closeEditor();
  };

  const duplicateTask = (task: Task) => {
    const id = allocateTaskId();

    setTasks((currentTasks) => [
      {
        ...task,
        id,
        title: `Copy of ${task.title}`,
      },
      ...currentTasks,
    ]);
  };

  const deleteTask = (task: Task) => {
    setTasks((currentTasks) =>
      currentTasks.filter((item) => item.id !== task.id)
    );
    setRowSelection((currentSelection) => {
      const { [task.id]: _deletedTask, ...remainingSelection } =
        currentSelection;
      return remainingSelection;
    });
  };

  const clearFilters = () => {
    setColumnFilters([]);
  };

  const columns = createTaskColumns({
    onDelete: deleteTask,
    onDuplicate: duplicateTask,
    onEdit: openEditEditor,
  });

  const table = useTable({
    columns,
    data: tasks,
    features: dataTableFeatures,
    getRowId: (task) => task.id,
    initialState: {
      pagination: {
        pageIndex: 0,
        pageSize: 6,
      },
    },
    onColumnFiltersChange: setColumnFilters,
    onColumnVisibilityChange: setColumnVisibility,
    onRowSelectionChange: setRowSelection,
    onSortingChange: setSorting,
    state: {
      columnFilters,
      columnVisibility,
      rowSelection,
      sorting,
    },
  });

  const queryFilter = table.getColumn("title")?.getFilterValue();
  const statusFilter = table.getColumn("status")?.getFilterValue();
  const priorityFilter = table.getColumn("priority")?.getFilterValue();
  const query = typeof queryFilter === "string" ? queryFilter : "";
  const status = typeof statusFilter === "string" ? statusFilter : null;
  const priority = typeof priorityFilter === "string" ? priorityFilter : null;
  const hasFilters = columnFilters.length > 0;
  const selectedTasks = table
    .getSelectedRowModel()
    .rows.map((row) => row.original);

  const moveSelectedTasks = (nextStatus: TaskStatus) => {
    const selectedIds = new Set(selectedTasks.map((task) => task.id));

    setTasks((currentTasks) =>
      currentTasks.map((task) =>
        selectedIds.has(task.id) ? { ...task, status: nextStatus } : task
      )
    );
    setRowSelection({});
  };

  const duplicateSelectedTasks = () => {
    const duplicates = selectedTasks.map((task, index) => ({
      ...task,
      id: `PRD-${nextTaskNumber + index}`,
      title: `Copy of ${task.title}`,
    }));

    if (duplicates.length === 0) {
      return;
    }

    setTasks((currentTasks) => [...duplicates, ...currentTasks]);
    setNextTaskNumber((current) => current + duplicates.length);
    setRowSelection({});
  };

  const deleteSelectedTasks = () => {
    const selectedIds = new Set(selectedTasks.map((task) => task.id));

    if (selectedIds.size === 0) {
      return;
    }

    setTasks((currentTasks) =>
      currentTasks.filter((task) => !selectedIds.has(task.id))
    );
    setRowSelection({});
  };

  return (
    <TaskSelectionActionBar
      onClearSelection={() => setRowSelection({})}
      onDelete={deleteSelectedTasks}
      onDuplicate={duplicateSelectedTasks}
      onMove={moveSelectedTasks}
      selectedCount={selectedTasks.length}
    >
      <div className="flex flex-col gap-4">
        <TaskFilters
          hasFilters={hasFilters}
          onClearFilters={clearFilters}
          onPriorityChange={(value) =>
            table.getColumn("priority")?.setFilterValue(value ?? undefined)
          }
          onQueryChange={(value) =>
            table.getColumn("title")?.setFilterValue(value)
          }
          onStatusChange={(value) =>
            table.getColumn("status")?.setFilterValue(value ?? undefined)
          }
          priority={priority as TaskDraft["priority"] | null}
          query={query}
          status={status as TaskDraft["status"] | null}
          table={table}
        />
        <TaskEditorDialog
          draft={draft}
          editor={editor}
          onDraftChange={setDraft}
          onOpenChange={(open) => {
            if (!open) {
              closeEditor();
            }
          }}
          onSubmit={saveTask}
        />
        <TaskGrid
          hasFilters={hasFilters}
          onClearFilters={clearFilters}
          onCreate={openCreateEditor}
          table={table}
        />
      </div>
    </TaskSelectionActionBar>
  );
};

"use client";

import { createColumnHelper } from "@tanstack/react-table";
import { CopyIcon, EllipsisIcon, PencilIcon, Trash2Icon } from "lucide-react";
import { cn } from "@/lib/utils";
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  DataTableColumnHeader,
  type DataTableFeatures,
} from "@/components/ui/data-table";
import {
  Menu,
  MenuContent,
  MenuItem,
  MenuTrigger,
} from "@/components/ui/menu";
import { Status } from "@/components/ui/status";
import {
  ASSIGNEES,
  priorityIconMap,
  statusIndicatorVariantMap,
  type Task,
  type TaskPriority,
  type TaskStatus,
} from "@/components/tasks/data/tasks";
import { priorityIconVariants } from "@/components/tasks/task-priority";

const columnHelper = createColumnHelper<DataTableFeatures, Task>();

export const columnWidthClasses: Record<string, string> = {
  actions: "w-12",
  assigned: "w-40",
  id: "w-28",
  priority: "w-24",
  status: "w-32",
  title: "w-64 min-w-0",
};

export interface TaskTableActions {
  onDelete: (task: Task) => void;
  onDuplicate: (task: Task) => void;
  onEdit: (task: Task) => void;
}

export const TaskStatusBadge = ({ status }: { status: TaskStatus }) => (
  <Badge className="gap-1.5" size="sm" variant="outline">
    <Status size="sm" variant={statusIndicatorVariantMap[status]} />
    {status}
  </Badge>
);

export const TaskPriorityLabel = ({ priority }: { priority: TaskPriority }) => {
  const PriorityIcon = priorityIconMap[priority];

  return (
    <span className="inline-flex items-center gap-1.5 font-medium text-sm">
      <PriorityIcon
        aria-hidden
        className={cn("size-3.5", priorityIconVariants({ priority }))}
      />
      {priority}
    </span>
  );
};

export const TaskRowMenu = ({
  onDelete,
  onDuplicate,
  onEdit,
  task,
}: TaskTableActions & { task: Task }) => (
  <Menu>
    <MenuTrigger asChild>
      <Button
        aria-label={`Open actions for ${task.id}`}
        size="icon-sm"
        variant="ghost"
      >
        <EllipsisIcon aria-hidden />
      </Button>
    </MenuTrigger>
    <MenuContent>
      <MenuItem onClick={() => onEdit(task)} value={`edit-${task.id}`}>
        <PencilIcon aria-hidden />
        Edit task
      </MenuItem>
      <MenuItem
        onClick={() => onDuplicate(task)}
        value={`duplicate-${task.id}`}
      >
        <CopyIcon aria-hidden />
        Duplicate task
      </MenuItem>
      <MenuItem
        onClick={() => onDelete(task)}
        value={`delete-${task.id}`}
        variant="destructive"
      >
        <Trash2Icon aria-hidden />
        Delete task
      </MenuItem>
    </MenuContent>
  </Menu>
);

export const createTaskColumns = (actions: TaskTableActions) => {
  const { onDelete, onDuplicate, onEdit } = actions;

  return columnHelper.columns([
    columnHelper.accessor("id", {
      cell: ({ row }) => (
        <div className="flex items-center gap-2">
          <Checkbox
            aria-label={`Select ${row.original.id}`}
            checked={row.getIsSelected()}
            onCheckedChange={({ checked }) => row.toggleSelected(!!checked)}
          />
          <span className="font-mono text-xs tabular-nums">
            {row.original.id}
          </span>
        </div>
      ),
      header: ({ column, table }) => (
        <div className="flex items-center gap-2">
          <Checkbox
            aria-label="Select all tasks on this page"
            checked={
              table.getIsAllPageRowsSelected() ||
              (table.getIsSomePageRowsSelected() && "indeterminate")
            }
            onCheckedChange={({ checked }) =>
              table.toggleAllPageRowsSelected(!!checked)
            }
          />
          <DataTableColumnHeader column={column} title="Task" />
        </div>
      ),
    }),
    columnHelper.accessor("title", {
      cell: ({ row }) => (
        <span className="block truncate font-medium" title={row.original.title}>
          {row.original.title}
        </span>
      ),
      filterFn: (row, _columnId, value) =>
        `${row.original.id} ${row.original.title}`
          .toLowerCase()
          .includes(String(value).toLowerCase()),
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Title" />
      ),
    }),
    columnHelper.accessor((task) => ASSIGNEES[task.assigneeId].name, {
      cell: ({ row }) => {
        const assignee = ASSIGNEES[row.original.assigneeId];

        return (
          <div className="flex min-w-0 items-center gap-2">
            <Avatar size="sm">
              <AvatarImage alt={assignee.name} src={assignee.avatar} />
              <AvatarFallback>{assignee.initials}</AvatarFallback>
            </Avatar>
            <span className="truncate font-medium">{assignee.name}</span>
          </div>
        );
      },
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Assigned" />
      ),
      id: "assigned",
    }),
    columnHelper.accessor("status", {
      cell: ({ row }) => <TaskStatusBadge status={row.original.status} />,
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Status" />
      ),
    }),
    columnHelper.accessor("priority", {
      cell: ({ row }) => <TaskPriorityLabel priority={row.original.priority} />,
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Priority" />
      ),
    }),
    columnHelper.display({
      cell: ({ row }) => (
        <TaskRowMenu
          onDelete={onDelete}
          onDuplicate={onDuplicate}
          onEdit={onEdit}
          task={row.original}
        />
      ),
      enableHiding: false,
      enableSorting: false,
      id: "actions",
    }),
  ]);
};

"use client";

import type { ReactTable } from "@tanstack/react-table";
import { SearchIcon, XIcon } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  type DataTableFeatures,
  DataTableViewOptions,
} from "@/components/ui/data-table";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@/components/ui/input-group";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
} from "@/components/ui/select";
import {
  FILTER_ALL,
  priorityFilterCollection,
  statusFilterCollection,
  type Task,
  type TaskPriority,
  type TaskStatus,
} from "@/components/tasks/data/tasks";
import {
  TaskAllOption,
  TaskPriorityOption,
  TaskPrioritySelectValue,
  TaskStatusOption,
  TaskStatusSelectValue,
} from "@/components/tasks/task-select-options";

export const TaskFilters = ({
  hasFilters,
  onClearFilters,
  onPriorityChange,
  onQueryChange,
  onStatusChange,
  priority,
  query,
  status,
  table,
}: {
  hasFilters: boolean;
  onClearFilters: () => void;
  onPriorityChange: (priority: TaskPriority | null) => void;
  onQueryChange: (query: string) => void;
  onStatusChange: (status: TaskStatus | null) => void;
  priority: TaskPriority | null;
  query: string;
  status: TaskStatus | null;
  table: ReactTable<DataTableFeatures, Task>;
}) => (
  <div className="flex flex-col gap-3 lg:flex-row lg:items-center">
    <InputGroup className="lg:max-w-48">
      <InputGroupAddon>
        <SearchIcon aria-hidden />
      </InputGroupAddon>
      <InputGroupInput
        aria-label="Search tasks"
        onChange={(event) => onQueryChange(event.target.value)}
        placeholder="Search"
        type="search"
        value={query}
      />
    </InputGroup>
    <div className="grid grid-cols-2 gap-2 sm:flex sm:flex-wrap sm:items-center">
      <Select
        collection={statusFilterCollection}
        onValueChange={({ value: [next] }) => {
          onStatusChange(
            !next || next === FILTER_ALL ? null : (next as TaskStatus)
          );
        }}
        value={[status ?? FILTER_ALL]}
      >
        <SelectTrigger className="w-full sm:w-35">
          <TaskStatusSelectValue placeholder="All" />
        </SelectTrigger>
        <SelectContent>
          {statusFilterCollection.items.map((item) => (
            <SelectItem item={item} key={item}>
              {item === FILTER_ALL ? (
                <TaskAllOption />
              ) : (
                <TaskStatusOption status={item as TaskStatus} />
              )}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      <Select
        collection={priorityFilterCollection}
        onValueChange={({ value: [next] }) => {
          onPriorityChange(
            !next || next === FILTER_ALL ? null : (next as TaskPriority)
          );
        }}
        value={[priority ?? FILTER_ALL]}
      >
        <SelectTrigger className="w-full sm:w-35">
          <TaskPrioritySelectValue placeholder="All" />
        </SelectTrigger>
        <SelectContent>
          {priorityFilterCollection.items.map((item) => (
            <SelectItem item={item} key={item}>
              {item === FILTER_ALL ? (
                <TaskAllOption />
              ) : (
                <TaskPriorityOption priority={item as TaskPriority} />
              )}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      {hasFilters ? (
        <Button
          className="col-span-2 sm:col-auto"
          onClick={onClearFilters}
          size="sm"
          variant="ghost"
        >
          <XIcon aria-hidden />
          Clear
        </Button>
      ) : null}
    </div>
    <DataTableViewOptions
      className="ms-0 hidden w-full sm:w-auto md:inline-flex lg:ms-auto"
      table={table}
      variant="outline"
    />
  </div>
);

