import type { Task } from "@/components/tasks/data/tasks";
import { columnWidthClasses } from "@/components/tasks/task-columns";
import { TaskEmptyState } from "@/components/tasks/task-empty-state";

export const TaskGrid = ({
  hasFilters,
  onClearFilters,
  onCreate,
  table,
}: {
  hasFilters: boolean;
  onClearFilters: () => void;
  onCreate: () => void;
  table: ReactTable<DataTableFeatures, Task>;
}) => {
  const hasTasks = table.getFilteredRowModel().rows.length > 0;

  if (!hasTasks) {
    return (
      <TaskEmptyState
        hasFilters={hasFilters}
        onClearFilters={onClearFilters}
        onCreate={onCreate}
      />
    );
  }

  return (
    <Card className="gap-0 py-0 [--space:0]">
      <div className="overflow-x-auto">
        <Table className="w-full min-w-0 table-fixed">
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <TableHead
                    className={columnWidthClasses[header.column.id]}
                    key={header.id}
                  >
                    {header.isPlaceholder ? null : (
                      <table.FlexRender header={header} />
                    )}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows.map((row) => (
              <TableRow className="h-13" key={row.id}>
                {row.getVisibleCells().map((cell) => (
                  <TableCell
                    className={
                      cell.column.id === "title" ? "min-w-0" : undefined
                    }
                    key={cell.id}
                  >
                    <table.FlexRender cell={cell} />
                  </TableCell>
                ))}
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>
      <CardFooter className="px-3 py-3 sm:px-4">
        <DataTablePagination table={table} />
      </CardFooter>
    </Card>
  );
};

"use client";

import { ClipboardListIcon } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  State,
  StateContent,
  StateDescription,
  StateHeader,
  StateMedia,
  StateTitle,
} from "@/components/ui/state";

export const TaskEmptyState = ({
  hasFilters,
  onClearFilters,
  onCreate,
}: {
  hasFilters: boolean;
  onClearFilters: () => void;
  onCreate: () => void;
}) => (
  <State className="min-h-88 border bg-muted/8 px-6 py-12 shadow-xs/4">
    <StateHeader>
      <StateMedia variant="icon">
        <ClipboardListIcon aria-hidden />
      </StateMedia>
      <StateTitle asChild>
        <h2>
          {hasFilters ? "No tasks match this view" : "Your sprint is clear"}
        </h2>
      </StateTitle>
      <StateDescription>
        {hasFilters
          ? "Try adjusting the filters, or create a task that belongs in this view."
          : "Create the first task to turn this sprint into a focused plan."}
      </StateDescription>
    </StateHeader>
    <StateContent className="!flex-row flex-wrap justify-center">
      {hasFilters ? (
        <Button onClick={onClearFilters} size="sm" variant="outline">
          Reset filters
        </Button>
      ) : null}
      <Button onClick={onCreate} size="sm">
        Create task
