"use client";

import type React from "react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogBody,
  DialogClose,
  DialogContent,
  DialogFooter,
  DialogHeader,
} from "@/components/ui/dialog";
import type { TaskDraft, TaskEditorState } from "@/components/tasks/data/tasks";
import { TaskEditorFields } from "@/components/tasks/task-editor-fields";

interface TaskEditorDialogProps {
  draft: TaskDraft;
  editor: TaskEditorState | null;
  onDraftChange: React.Dispatch<React.SetStateAction<TaskDraft>>;
  onOpenChange: (open: boolean) => void;
  onSubmit: (event: React.FormEvent<HTMLFormElement>) => void;
}

export const TaskEditorDialog = (props: TaskEditorDialogProps) => {
  const { draft, editor, onDraftChange, onOpenChange, onSubmit } = props;
  const isCreating = editor?.mode === "create";

  return (
    <Dialog onOpenChange={({ open }) => onOpenChange(open)} open={!!editor}>
      <DialogContent size="lg">
        <DialogHeader
          description={
            isCreating
              ? "Give it a title and an owner."
              : "Change the title, status, or owner."
          }
          title={isCreating ? "New task" : "Edit task"}
        />
        <form className="contents" onSubmit={onSubmit}>
          <DialogBody className="pt-1">
            <TaskEditorFields draft={draft} onDraftChange={onDraftChange} />
          </DialogBody>
          <DialogFooter>
            <DialogClose asChild>
              <Button variant="outline">Cancel</Button>
            </DialogClose>
            <Button disabled={!draft.title.trim()} type="submit">
              {isCreating ? "Create task" : "Save changes"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};

"use client";

import type { Select as ArkSelect } from "@ark-ui/react/select";
import type React from "react";
import {
  Field,
  FieldGroup,
  FieldLabel,
} from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
} from "@/components/ui/select";
import {
  assigneeCollection,
  priorityCollection,
  statusCollection,
  type TaskAssigneeId,
  type TaskDraft,
  type TaskPriority,
  type TaskStatus,
  type TaskType,
  typeCollection,
} from "@/components/tasks/data/tasks";
import {
  TaskAssigneeOption,
  TaskAssigneeSelectValue,
  TaskPriorityOption,
  TaskPrioritySelectValue,
  TaskStatusOption,
  TaskStatusSelectValue,
  TaskTypeOption,
  TaskTypeSelectValue,
} from "@/components/tasks/task-select-options";

interface TaskEditorSelectProps {
  itemKey: (item: ArkSelect.CollectionItem) => string;
  label: string;
  renderItem: (item: ArkSelect.CollectionItem) => React.ReactNode;
  selectValue: React.ReactNode;
}

const TaskEditorSelect: ArkSelect.RootComponent<TaskEditorSelectProps> = (
  props
) => {
  const {
    collection,
    itemKey,
    label,
    onValueChange,
    renderItem,
    selectValue,
    value,
  } = props;

  return (
    <Field>
      <FieldLabel>{label}</FieldLabel>
      <Select
        collection={collection}
        onValueChange={onValueChange}
        value={value}
      >
        <SelectTrigger className="w-full">{selectValue}</SelectTrigger>
        <SelectContent>
          {collection.items.map((item) => (
            <SelectItem item={item} key={itemKey(item)}>
              {renderItem(item)}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </Field>
  );
};

export const TaskEditorFields = ({
  draft,
  onDraftChange,
}: {
  draft: TaskDraft;
  onDraftChange: React.Dispatch<React.SetStateAction<TaskDraft>>;
}) => {
  const patchDraft = <K extends keyof TaskDraft>(
    key: K,
    value: TaskDraft[K]
  ) => {
    onDraftChange((current) => ({ ...current, [key]: value }));
  };

  return (
    <FieldGroup className="gap-5">
      <Field className="sm:col-span-2">
        <FieldLabel>Task title</FieldLabel>
        <Input
          onChange={(event) => patchDraft("title", event.target.value)}
          placeholder="Describe the work clearly"
          value={draft.title}
        />
      </Field>
      <div className="grid gap-5 border-t pt-5 sm:grid-cols-2">
        <TaskEditorSelect
          collection={typeCollection}
          itemKey={(item) => item.value}
          label="Type"
          onValueChange={({ value }) =>
            patchDraft("type", (value[0] ?? "") as TaskType)
          }
          renderItem={(item) => (
            <TaskTypeOption type={item.value as TaskType} />
          )}
          selectValue={<TaskTypeSelectValue />}
          value={[draft.type]}
        />
        <TaskEditorSelect
          collection={priorityCollection}
          itemKey={(item) => item}
          label="Priority"
          onValueChange={({ value }) =>
            patchDraft("priority", (value[0] ?? "") as TaskPriority)
          }
          renderItem={(item) => <TaskPriorityOption priority={item} />}
          selectValue={<TaskPrioritySelectValue />}
          value={[draft.priority]}
        />
        <TaskEditorSelect
          collection={statusCollection}
          itemKey={(item) => item}
          label="Status"
          onValueChange={({ value }) =>
            patchDraft("status", (value[0] ?? "") as TaskStatus)
          }
          renderItem={(item) => <TaskStatusOption status={item} />}
          selectValue={<TaskStatusSelectValue />}
          value={[draft.status]}
        />
        <TaskEditorSelect
          collection={assigneeCollection}
          itemKey={(item) => item.value}
          label="Assigned"
          onValueChange={({ value }) =>
            patchDraft("assigneeId", (value[0] ?? "") as TaskAssigneeId)
          }
          renderItem={(item) => (
            <TaskAssigneeOption assigneeId={item.value as TaskAssigneeId} />
          )}
          selectValue={<TaskAssigneeSelectValue />}
          value={[draft.assigneeId]}
        />
      </div>
    </FieldGroup>
  );
};

import {
  BugIcon,
  FileTextIcon,
  LightbulbIcon,
  ListFilterIcon,
} from "lucide-react";
import { cn } from "@/lib/utils";
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from "@/components/ui/avatar";
import { SelectContext, SelectValue } from "@/components/ui/select";
import { Status } from "@/components/ui/status";
import {
  ASSIGNEES,
  FILTER_ALL,
  priorityIconMap,
  statusIndicatorVariantMap,
  type TaskAssigneeId,
  type TaskPriority,
  type TaskStatus,
  type TaskType,
} from "@/components/tasks/data/tasks";
import { priorityIconVariants } from "@/components/tasks/task-priority";

const typeIconMap = {
  Bug: BugIcon,
  Documentation: FileTextIcon,
  Feature: LightbulbIcon,
};

export const TaskAllOption = () => (
  <>
    <ListFilterIcon aria-hidden className="size-4 text-muted-foreground" />
    All
  </>
);

export const TaskTypeOption = ({ type }: { type: TaskType }) => {
  const TypeIcon = typeIconMap[type];

  return (
    <>
      <TypeIcon aria-hidden className="size-4 text-muted-foreground" />
      {type}
    </>
  );
};

export const TaskPriorityOption = ({
  priority,
}: {
  priority: TaskPriority;
}) => {
  const PriorityIcon = priorityIconMap[priority];

  return (
    <>
      <PriorityIcon
        aria-hidden
        className={cn("size-4", priorityIconVariants({ priority }))}
      />
      {priority}
    </>
  );
};

export const TaskStatusOption = ({ status }: { status: TaskStatus }) => (
  <>
    <Status size="sm" variant={statusIndicatorVariantMap[status]} />
    {status}
  </>
);

export const TaskAssigneeOption = ({
  assigneeId,
}: {
  assigneeId: TaskAssigneeId;
}) => {
  const assignee = ASSIGNEES[assigneeId];

  return (
    <>
      <Avatar size="sm">
        <AvatarImage alt={assignee.name} src={assignee.avatar} />
        <AvatarFallback>{assignee.initials}</AvatarFallback>
      </Avatar>
      {assignee.name}
    </>
  );
};

export const TaskTypeSelectValue = () => (
  <SelectValue placeholder="Select a type">
    <SelectContext>
      {({ value }) => {
        const type = value[0] as TaskType | undefined;
        return type ? <TaskTypeOption type={type} /> : null;
      }}
    </SelectContext>
  </SelectValue>
);

export const TaskPrioritySelectValue = ({
  placeholder = "Select a priority",
}) => (
  <SelectValue placeholder={placeholder}>
    <SelectContext>
      {({ value: [priority] }) => {
        if (!priority) {
          return null;
        }
        if (priority === FILTER_ALL) {
          return <TaskAllOption />;
        }
        return <TaskPriorityOption priority={priority as TaskPriority} />;
      }}
    </SelectContext>
  </SelectValue>
);

export const TaskStatusSelectValue = ({ placeholder = "Select a status" }) => (
  <SelectValue placeholder={placeholder}>
    <SelectContext>
      {({ value: [status] }) => {
        if (!status) {
          return null;
        }
        if (status === FILTER_ALL) {
          return <TaskAllOption />;
        }
        return <TaskStatusOption status={status as TaskStatus} />;
      }}
    </SelectContext>
  </SelectValue>
);

export const TaskAssigneeSelectValue = () => (
  <SelectValue placeholder="Select an owner">
    <SelectContext>
      {({ value }) => {
        const assigneeId = value[0] as TaskAssigneeId | undefined;
        return assigneeId ? (
          <TaskAssigneeOption assigneeId={assigneeId} />
        ) : null;
      }}
    </SelectContext>
  </SelectValue>
);

"use client";

import {
  ArrowRightIcon,
  CheckIcon,
  CopyIcon,
  EllipsisIcon,
  ListRestartIcon,
  Trash2Icon,
  XIcon,
} from "lucide-react";
import type React from "react";
import {
  ActionBar,
  ActionBarBody,
  ActionBarClose,
  ActionBarContent,
  ActionBarSeparator,
  ActionBarValue,
} from "@/components/ui/action-bar";
import { Button } from "@/components/ui/button";
import {
  Menu,
  MenuContent,
  MenuItem,
  MenuTrigger,
} from "@/components/ui/menu";
import type { TaskStatus } from "@/components/tasks/data/tasks";

interface TaskSelectionActionBarProps {
  children: React.ReactNode;
  onClearSelection: () => void;
  onDelete: () => void;
  onDuplicate: () => void;
  onMove: (status: TaskStatus) => void;
  selectedCount: number;
}

export const TaskSelectionActionBar = ({
  children,
  onClearSelection,
  onDelete,
  onDuplicate,
  onMove,
  selectedCount,
}: TaskSelectionActionBarProps) => (
  <ActionBar
    onOpenChange={({ open }) => {
      if (!open) {
        onClearSelection();
      }
    }}
    open={selectedCount > 0}
  >
    {children}
    <ActionBarContent aria-label="Actions for selected tasks">
      <ActionBarValue count={selectedCount}>
        {selectedCount} selected
      </ActionBarValue>
      <ActionBarSeparator />
      <ActionBarBody>
        <Button
          aria-label="Duplicate selected tasks"
          onClick={onDuplicate}
          size="icon-sm"
          variant="ghost"
        >
          <CopyIcon aria-hidden />
        </Button>
        <Button
          aria-label="Mark selected tasks as done"
          onClick={() => onMove("Done")}
          size="icon-sm"
          variant="ghost"
        >
          <CheckIcon aria-hidden />
        </Button>
        <Menu positioning={{ placement: "top" }}>
          <MenuTrigger asChild>
            <Button
              aria-label="More task actions"
              size="icon-sm"
              variant="ghost"
            >
              <EllipsisIcon aria-hidden />
            </Button>
          </MenuTrigger>
          <MenuContent>
            <MenuItem
              onClick={() => onMove("In Progress")}
              value="move-to-active"
            >
              <ArrowRightIcon aria-hidden />
              Move to active
            </MenuItem>
            <MenuItem onClick={() => onMove("Backlog")} value="move-to-backlog">
              <ListRestartIcon aria-hidden />
              Move to backlog
            </MenuItem>
            <MenuItem
              onClick={() => onMove("Canceled")}
              value="cancel-tasks"
              variant="destructive"
            >
              <XIcon aria-hidden />
              Cancel tasks
            </MenuItem>
          </MenuContent>
        </Menu>
        <ActionBarSeparator />
        <Button
          aria-label="Delete selected tasks"
          onClick={onDelete}
          size="icon-sm"
          variant="destructive"
        >
          <Trash2Icon aria-hidden />
        </Button>
      </ActionBarBody>
      <ActionBarSeparator />
      <ActionBarClose asChild onClick={onClearSelection}>
        <Button aria-label="Clear selection" size="icon-sm" variant="ghost">
          <XIcon aria-hidden />
        </Button>
      </ActionBarClose>
    </ActionBarContent>
  </ActionBar>
);
